// Rigged, textured GLB characters replace these lightweight placeholders as soon as they load.
function makePerson(isCop=false){
 const g=new THREE.Group(), top=isCop?uniform:blue, legmat=isCop?policeBlue:pants;
 const torso=capsule(g,.31,.57,top,0,1.25,0);torso.scale.set(.92,1,.62);
 box(g,.58,.12,isCop?.34:.32,legmat,0,.96,0);sphere(g,.22,skin,0,1.88,0,.88,1.08,.82);
 if(isCop){box(g,.48,.12,.43,policeBlue,0,2.09,0);sphere(g,.1,gold,0,2.17,-.02,1,.36,.25);}
 else sphere(g,.225,mat(0x292321),0,2.01,-.015,1,.5,.9);
 const limbs=[];
 for(const s of [-1,1]){const arm=new THREE.Group();arm.position.set(s*.36,1.53,0);g.add(arm);capsule(arm,.115,.43,top,0,-.25,0);sphere(arm,.09,skin,0,-.53,-.01);limbs.push(arm);const leg=new THREE.Group();leg.position.set(s*.17,.94,0);g.add(leg);capsule(leg,.135,.48,legmat,0,-.29,0);box(leg,.22,.12,.4,dark,0,-.57,-.1);limbs.push(leg);}
 return {group:g,limbs,mixer:null};
}
const player=makePerson(false);scene.add(player.group);player.group.position.set(0,0,0);
const cop=makePerson(true);scene.add(cop.group);cop.group.position.set(0,0,4.2);cop.group.scale.set(.9,.9,.9);
const gltfLoader=new GLTFLoader();
async function loadCharacter(character,path,height,scale=1){
 try{
  const gltf=await gltfLoader.loadAsync(path), model=gltf.scene;
  model.updateMatrixWorld(true);let bounds=new THREE.Box3().setFromObject(model),size=bounds.getSize(new THREE.Vector3());
  if(!Number.isFinite(size.y)||size.y===0)throw new Error('الشخصية بلا أبعاد صالحة');
  model.scale.multiplyScalar(height/size.y);model.updateMatrixWorld(true);bounds.setFromObject(model);
  model.position.x-=(bounds.min.x+bounds.max.x)/2;model.position.y-=bounds.min.y;model.position.z-=(bounds.min.z+bounds.max.z)/2;
  model.traverse(node=>{if(node.isMesh){node.castShadow=true;node.receiveShadow=true;}});
  character.group.parent?.remove(character.group);
  const rig=new THREE.Group();rig.position.copy(character.group.position);rig.scale.setScalar(scale);rig.add(model);scene.add(rig);
  character.group=rig;character.limbs=[];
  if(gltf.animations.length){character.mixer=new THREE.AnimationMixer(model);character.mixer.clipAction(gltf.animations[0]).reset().play();}
 }catch(error){console.warn(`تعذر تحميل ${path}، سيستمر اللعب بالشخصية البديلة.`,error);}
}
Promise.all([loadCharacter(player,'/models/runner.glb',2.08),loadCharacter(cop,'/models/police.glb',2.08,.9)]);

