const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright-core');
(async () => {
  const browser = await chromium.launch({ executablePath: '/usr/bin/chromium', headless: true, args: ['--no-sandbox', '--disable-dev-shm-usage'] });
  const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
  const errors = [], modelResponses = [];
  page.on('pageerror', e => errors.push(`pageerror: ${e.message}`));
  page.on('console', m => { if (m.type() === 'error' || m.type() === 'warning') errors.push(`${m.type()}: ${m.text()}`); });
  page.on('requestfailed', r => errors.push(`failed: ${r.url()} ${r.failure()?.errorText}`));
  page.on('response', r => { if (r.url().includes('.glb')) modelResponses.push(`${r.status()} ${r.url()}`); });
  await page.goto('http://127.0.0.1:8766', { waitUntil: 'networkidle', timeout: 60000 });
  await page.waitForTimeout(5000);
  console.log('canvas', await page.locator('canvas').count(), 'modelResponses', JSON.stringify(modelResponses), 'errors', JSON.stringify(errors));
  await page.screenshot({ path: '/tmp/opencode/game-menu-good.png' });
  await page.locator('#start').click();
  await page.waitForTimeout(1500);
  console.log('hud', await page.locator('#hud').getAttribute('class'), 'distance', await page.locator('#distance').textContent());
  await page.screenshot({ path: '/tmp/opencode/game-play-good.png' });
  await page.keyboard.press('ArrowLeft');
  await page.keyboard.press('ArrowUp');
  await page.setViewportSize({ width: 390, height: 844 });
  await page.waitForTimeout(500);
  const cdp = await page.context().newCDPSession(page);
  await cdp.send('Input.setTouchEmulationEnabled', { enabled: true, maxTouchPoints: 1 });
  await cdp.send('Input.dispatchTouchEvent', { type: 'touchStart', touchPoints: [{ x: 190, y: 590, id: 1 }] });
  await cdp.send('Input.dispatchTouchEvent', { type: 'touchMove', touchPoints: [{ x: 300, y: 590, id: 1 }] });
  await cdp.send('Input.dispatchTouchEvent', { type: 'touchEnd', touchPoints: [] });
  await page.waitForTimeout(500);
  await page.screenshot({ path: '/tmp/opencode/game-mobile-good.png' });
  console.log('final errors', JSON.stringify(errors));
  await browser.close();
})().catch(e => { console.error(e); process.exit(1); });

